t.script:
/* ── read data ── */
var AP_SUBTYPE = JSON.parse(document.getElementById('apSubtype').textContent);
var AP_FORM    = JSON.parse(document.getElementById('apForm').textContent);
var AP_PRICES  = JSON.parse(document.getElementById('apPrices').textContent);
var AP_TOP3    = JSON.parse(document.getElementById('apTop3').textContent);

/* ── navigate to form ── */
function apSelect(card) {
    window.location.href = AP_FORM
        + '?pricing_id=' + encodeURIComponent(card.dataset.id)
        + '&premium=' + encodeURIComponent(card.dataset.premium)
        + '&company=' + encodeURIComponent(card.dataset.company);
}

/* ── build a comparison card using DOM only (no HTML strings) ── */
function apMakeCard(p, rank) {
    var colors  = ['#344B9B', '#5CAFE4', '#84CFFF'];
    var medals  = ['\uD83E\uDD47 الأوفر سعراً', '\uD83E\uDD48 الأشمل تغطية', '\uD83E\uDD49 الأعلى جودة'];
    var color   = colors[rank] || '#344B9B';

    var wrap = document.createElement('div');
    wrap.dataset.pricingId = p.id;
    wrap.style.cssText = 'flex:1;min-width:210px;max-width:320px;border:2.5px solid ' + color
        + ';border-radius:14px;padding:24px 20px;text-align:center;background:'
        + (rank === 0 ? '#EEF2FF' : '#fff')
        + ';box-shadow:0 4px 18px rgba(52,75,155,.12);cursor:pointer;'
        + 'transition:transform .2s;position:relative;';

    if (rank === 0) {
        var badge = document.createElement('div');
        badge.style.cssText = 'position:absolute;top:-12px;right:50%;transform:translateX(50%);'
            + 'background:#344B9B;color:#fff;padding:3px 16px;border-radius:100px;'
            + 'font-size:11px;font-weight:800;white-space:nowrap;';
        badge.textContent = '\u2B50 الأفضل';
        wrap.appendChild(badge);
    }

    var medal = document.createElement('div');
    medal.style.cssText = 'font-size:12px;font-weight:700;color:' + color + ';margin-bottom:8px;margin-top:' + (rank === 0 ? '8' : '0') + 'px;';
    medal.textContent = medals[rank] || '';
    wrap.appendChild(medal);

    var coName = document.createElement('div');
    coName.style.cssText = 'font-size:18px;font-weight:900;color:#1a1a2e;margin-bottom:10px;';
    coName.textContent = p.company_name;
    wrap.appendChild(coName);

    var prem = document.createElement('div');
    prem.style.cssText = 'font-size:36px;font-weight:900;color:' + color + ';line-height:1;';
    prem.textContent = parseFloat(p.base_premium).toFixed(3);
    wrap.appendChild(prem);

    var cur = document.createElement('div');
    cur.style.cssText = 'font-size:13px;color:#666;margin:4px 0 18px;';
    cur.textContent = 'ر.ع / سنوياً';
    wrap.appendChild(cur);

    var btn = document.createElement('button');
    btn.style.cssText = 'width:100%;padding:11px;background:#344B9B;color:#fff;'
        + 'border:none;border-radius:9px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;';
    btn.textContent = 'اختر هذا العرض ←';
    wrap.appendChild(btn);

    wrap.addEventListener('mouseenter', function() { wrap.style.transform = 'translateY(-4px)'; });
    wrap.addEventListener('mouseleave', function() { wrap.style.transform = 'translateY(0)'; });
    wrap.addEventListener('click', function() {
        window.location.href = AP_FORM
            + '?pricing_id=' + encodeURIComponent(p.id)
            + '&premium=' + encodeURIComponent(p.base_premium)
            + '&company=' + encodeURIComponent(p.company_name);
    });
    return wrap;
}

/* ── build fallback section (DOM only) ── */
function apBuildFallback(prices) {
    var section = document.createElement('div');
    section.style.cssText = 'font-family:inherit;direction:rtl;padding:20px;';

    var title = document.createElement('p');
    title.style.cssText = 'text-align:center;color:#344B9B;font-size:15px;font-weight:700;margin:0 0 6px;';
    title.textContent = '\uD83E\uDD16 صحاب AI — أفضل 3 عروض منتقاة';
    section.appendChild(title);

    var sub = document.createElement('p');
    sub.style.cssText = 'text-align:center;color:#888;font-size:12px;margin:0 0 20px;';
    sub.textContent = 'انقر على أي عرض للمتابعة';
    section.appendChild(sub);

    var row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:16px;flex-wrap:wrap;justify-content:center;';
    prices.forEach(function(p, i) { row.appendChild(apMakeCard(p, i)); });
    section.appendChild(row);
    return section;
}

/* ── call Sahab AI ── */
async function apLoadAI() {
    var frame = document.getElementById('ai-frame');
    var badge = document.getElementById('ai-badge');
    try {
        var resp = await fetch('/ameen/pricing/ai-compare', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ subtype_id: AP_SUBTYPE, prices: AP_PRICES })
        });
        if (!resp.ok) throw new Error(resp.status);
        var data = await resp.json();
        if (data.html) {
            frame.innerHTML = data.html;
            badge.textContent = '\u2705 تحليل صحاب AI';
            badge.style.background = '#D1FAE5';
            badge.style.color = '#065F46';
            frame.querySelectorAll('[data-pricing-id]').forEach(function(el) {
                el.style.cursor = 'pointer';
                el.addEventListener('click', function() {
                    var pid  = el.dataset.pricingId;
                    var pObj = AP_PRICES.find(function(x) { return String(x.id) === String(pid); });
                    window.location.href = AP_FORM
                        + '?pricing_id=' + encodeURIComponent(pid)
                        + '&premium=' + encodeURIComponent(pObj ? pObj.base_premium : '')
                        + '&company=' + encodeURIComponent(pObj ? pObj.company_name : '');
                });
            });
        } else {
            frame.innerHTML = '';
            frame.appendChild(apBuildFallback(AP_TOP3));
            badge.textContent = '\u2705 أفضل 3 أسعار';
            badge.style.background = '#D1FAE5';
            badge.style.color = '#065F46';
        }
    } catch(e) {
        if (AP_TOP3.length) {
            frame.innerHTML = '';
            frame.appendChild(apBuildFallback(AP_TOP3));
            badge.textContent = '\u26A1 عرض سريع';
            badge.style.background = '#FEF3C7';
            badge.style.color = '#92400E';
        } else {
            frame.innerHTML = '';
            var msg = document.createElement('div');
            msg.style.cssText = 'padding:40px;text-align:center;color:#888;font-size:13px;';
            msg.textContent = 'لا توجد أسعار للمقارنة';
            frame.appendChild(msg);
            badge.textContent = '\u2014';
        }
    }
}

document.addEventListener('DOMContentLoaded', function() { setTimeout(apLoadAI, 600); });
